/*
      色は必ず `rgb(var(--x) / <alpha-value>)` の形で渡す。
      素の `var(--x)` にすると、Tailwind が色として読めず
      **不透明度の指定（border-ads-border/30 など）が黙って落ちる**。
    */
    tailwind.config = {
      theme: {
        extend: {
          colors: {
            ads: {
              bg:          'rgb(var(--ads-bg) / <alpha-value>)',
              surface:     'rgb(var(--ads-surface) / <alpha-value>)',
              'surface-2': 'rgb(var(--ads-surface-2) / <alpha-value>)',
              border:      'rgb(var(--ads-border) / <alpha-value>)',
              text:        'rgb(var(--ads-text) / <alpha-value>)',
              body:        'rgb(var(--ads-body) / <alpha-value>)',
              muted:       'rgb(var(--ads-muted) / <alpha-value>)',
              line:        'rgb(var(--ads-line) / <alpha-value>)',
              accent:      'rgb(var(--ads-accent) / <alpha-value>)',
              positive:    'rgb(var(--ads-positive) / <alpha-value>)',
              negative:    'rgb(var(--ads-negative) / <alpha-value>)',
            }
          },
          // 色を書かずに `border` だけ書いたときの既定。
          // これが無いと Tailwind の既定（gray-200）が暗い側でも白く残る
          borderColor: { DEFAULT: 'rgb(var(--ads-border))' },
          // 書体は OS の書体が先頭（Pages の画面と同じ考え方。Web フォントを待たない）。
          // Windows は欧文を Segoe UI、和文を Yu Gothic UI で出す。Yu Gothic UI は標準・太字を
          // 本物の字形で持つので、本文が細く出ず、見出しの太字も合成にならない（900 は持たないので太字で出る）。
          // 游ゴシックの「Medium」を先に置かないのは、あれが 1 つの太さしか持たず太字が合成になるため。
