          // 図を貼る一式（src/templates/mermaid.html）も同じ並びを持つ
          fontFamily: {
            sans: ['-apple-system', 'BlinkMacSystemFont', '"Hiragino Sans"', '"Hiragino Kaku Gothic ProN"', '"Segoe UI"', '"Yu Gothic UI"', '"Meiryo"', '"Noto Sans JP"', 'sans-serif'],
          }
