lucide.createIcons();
    // 先頭へ戻るの出し入れと、押されたときの動き。
    //
    // 頭へ運ぶのは自分でやる。滑らかさと「動きを減らす」設定は、上の scroll-behavior が持つ。
    (() => {
      const button = document.getElementById("sp-to-top");
      if (!button) return;
      button.addEventListener("click", () => {
        document.getElementById("sp-top").scrollIntoView();
      });
      // 出る境目と隠れる境目をずらす。1 点で切り替えると、その付近を行き来する
      // 小さな上下（慣性スクロールの揺り戻しなど）でボタンが点滅する
      const SHOW = 320;
      const HIDE = 160;
      let waiting = false;
      const sync = () => {
        waiting = false;
        const y = window.scrollY;
        const hidden = button.hasAttribute("data-ads-at-top");
        if (hidden && y > SHOW) button.removeAttribute("data-ads-at-top");
        else if (!hidden && y < HIDE) button.setAttribute("data-ads-at-top", "");
      };
      // scroll は 1 回の指の動きで何十回も来る。描画の 1 コマにつき 1 回へ間引く
      window.addEventListener("scroll", () => {
        if (waiting) return;
        waiting = true;
        requestAnimationFrame(sync);
      }, { passive: true });
      sync();
    })();
